CREATE TABLE IF NOT EXISTS file_collection_config (
  code VARCHAR(60) NOT NULL,
  config_version INT NOT NULL,
  name VARCHAR(100) NOT NULL,
  enabled TINYINT NOT NULL DEFAULT 1,
  config_json JSON NOT NULL,
  PRIMARY KEY (code, config_version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS file_collection_batch (
  id CHAR(36) PRIMARY KEY,
  config_code VARCHAR(60) NOT NULL,
  config_version INT NOT NULL,
  config_hash CHAR(64) NOT NULL,
  config_snapshot JSON NOT NULL,
  file_hash CHAR(64) NOT NULL,
  source_file VARCHAR(200) NOT NULL,
  business_date DATE NOT NULL,
  date_basis VARCHAR(200) NOT NULL,
  imported_at DATETIME NOT NULL,
  raw_count INT NOT NULL,
  value_count INT NOT NULL,
  UNIQUE KEY uk_file_collection_batch (config_code, config_version, file_hash, business_date),
  KEY idx_file_collection_date (config_code, business_date, imported_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS file_collection_raw (
  batch_id CHAR(36) NOT NULL,
  object_name VARCHAR(200) NOT NULL,
  source_row INT NOT NULL,
  field_name VARCHAR(200) NOT NULL,
  raw_text VARCHAR(200) NOT NULL,
  metric_value DECIMAL(18,4) NULL,
  unit VARCHAR(20) NOT NULL,
  source_cell VARCHAR(500) NOT NULL,
  source_rule TEXT,
  PRIMARY KEY (batch_id, object_name, field_name),
  CONSTRAINT fk_file_raw_batch FOREIGN KEY (batch_id) REFERENCES file_collection_batch(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS file_collection_value (
  batch_id CHAR(36) NOT NULL,
  metric_code VARCHAR(100) NOT NULL,
  source_row INT NOT NULL,
  group_name VARCHAR(200) NOT NULL,
  source_scope VARCHAR(200) NOT NULL,
  metric_name VARCHAR(200) NOT NULL,
  metric_value DECIMAL(18,4) NULL,
  unit VARCHAR(20) NOT NULL,
  value_status VARCHAR(30) NOT NULL,
  calculation_note TEXT,
  source_cell VARCHAR(500) NOT NULL,
  definition TEXT,
  statistical_rule TEXT,
  threshold_note TEXT,
  PRIMARY KEY (batch_id, metric_code),
  CONSTRAINT fk_file_value_batch FOREIGN KEY (batch_id) REFERENCES file_collection_batch(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

